INSERT INTO `bai_dang_cho_thue` VALUES (1,1,'CHO THUÊ PHÒNG TRỌ CHÍNH CHỦ TÂN TRIỀU- TRIỀU KHÚC -THANH XUÂN ( PHÙ HỢP VỚI NHÓM BẠN Ở 3-4 NGƯỜI)','Thông tin mô tả\nChính chủ cho thuê CCMN hoặc ở ghép cùng nhau .Địa chỉ : Số nhà 50, ngõ 46 Tân Triều, Triều Khúc, Thanh Xuân\nĐiện thoại: 0987570095\n---------------------------------------------\nTHÔNG TIN CHI TIẾT\nNhà không chung chủ, đi lại tự do - thoải mái giờ giấc\nKhu vực dân trí cao, an ninh đảm bảo ( Có bảo vệ 24h), ra vào bằng khóa cửa vân tay\nGần chợ, gần các trường đại học, đường đoạn này thoáng.\nNhà Full nội thất,điều hòa nóng lạnh, tủ quần áo, gác xép, bàn ăn, giường\nNVS khép kín\nGiá :3TR9\nỞ đây miễn phí gửi xe ( không giới hạn số xe)\nĐiện: 4k/ số\nNước: 30k/ khối','Thanh Xuân, Hà Nội','Thanh Xuân',' Hà Nội',20.9959212,105.8040796,3900000,30,'APPROVED',NULL,'2025-10-25 09:59:49','2025-11-17 14:35:11'),(2,1,'PHÒNG ĐẸP MỚI TINH TẠI 435 ĐỘI CẤN TRUNG TÂM BA ĐÌNH','Thông tin mô tả\n- Vị trí siêu tiện: chỉ vài phút ra Hồ Tây, Lotte Center, Liễu Giai.\n- Phòng rộng thoáng, đầy đủ nội thất: giường, tủ, điều hòa, máy giặt riêng, ban công mát mẻ, bếp tách riêng\n- Tòa nhà sạch sẽ an ninh tốt thang máy ra vào thoải mái.\n- Wifi mạnh, phù hợp cho người đi làm hoặc khách nước ngoài.','Ba Đình, Hà Nội','Ba Đình',' Hà Nội',21.0358515,105.8260943,7000000,30,'APPROVED',NULL,'2025-10-25 09:59:49','2025-11-17 14:35:33'),(3,1,'PHÒNG TỐT - GIÁ TỐT TẠI MỄ TRÌ HẠ, FULL ĐỒ, Ở NGAY','Thông tin mô tả\nPHÒNG TỐT - GIÁ TỐT\nĐịa chỉ: Số 6 ngõ 57 Mễ Trì Hạ, Nam Từ Liêm, Hà Nội\nGiá phòng: Từ 4.600.000 đ/tháng (tùy trục)\nLoại hình phòng: Phòng trọ khép kín, dạng studio\n️ Nội thất: Full đồ gồm giường, điều hòa, tủ lạnh, tủ quần áo, bàn ghế, bàn bếp, tủ bếp, hút mùi, nóng lạnh. Có máy giặt chung tầng 1, thang máy, thang thoát hiểm.\nLiên hệ/Zalo: 0977829586','Nam Từ Liêm, Hà Nội','Nam Từ Liêm',' Hà Nội',21.0034608,105.7703287,4600000,28,'APPROVED',NULL,'2025-10-25 09:59:49','2025-11-17 14:35:33'),(4,1,'TƯNG BỪNG KHAI TRƯƠNG CƠ SỞ MỚI TẠI 67PHÙNG KHOANG– NGAY CHỢ SINH VIÊN – 1 BƯỚC CHÂN VẠN TIỆNÍCH GIÁ','Thông tin mô tả\nTưng bừng Khai Trương Cơ Sở Mới tại PHÙNG KHOANG– ngay chợ sinh Viên – 1 bước chân vạn tiện ích giá hạt rẻ chỉ từ 990k -1.2tr / tháng giảm ngay 30% cho khách mớiii.\nBạn đang tìm một căn phòng “xịn xò” một chút, đầy đủ tiện nghi một chút, nhưng giá cả lại phải “hạt dẻ” một chút?\nStop ngay lại! Vì homestay ngõ 67 Phùng Khoang chính là dành cho bạn!\nMình khoe với các bạn “bảo bối” trong từng căn phòng nè:\n️ Giường ngủ êm ái, nệm dày dặn sau một ngày dài học tập và làm việc.\n️ Tủ quần áo rộng rãi, tha hồ “tậu” đồ mới.\nBàn học/làm việc riêng tư, đầy đủ ánh sáng.\n️ Điều hòa mát lạnh, quạt trần thoáng đãng.\n️ Bình nóng lạnh “cực nhanh cực nóng”, tắm mùa đông không lo.\nĂn uống: Chợ Phùng Khoang, siêu thị, hàng quán ăn sáng, trà chanh, cà phê… đủ cả.\nHọc tập: Gần các trường ĐH, Cao đẳng, thuận tiện đi lại.\nDi chuyển: Dễ dàng kết nối ra các trục đường chính, gần đường Nguyễn Trãi, Trần Phú.\nY tế: Các phòng khám, hiệu thuốc gần ngay sát bên.\nVà tất nhiên, vị trí “quá đỉnh”: Ngõ 67 rộng rãi, ô tô đỗ cửa luôn!\nNHANH TAY INBOX hỏi giá và đặt lịch xem phòng ngay hôm nay, kẻo lỡ “hụt” phòng đẹp các bạn ơi!\nLiên hệ chủ nhà” 0702146959','Thanh Xuân, Hà Nội','Thanh Xuân',' Hà Nội',20.9959212,105.8040796,990000,50,'APPROVED',NULL,'2025-10-25 09:59:49','2025-11-17 14:35:33'),(5,1,'PHÒNG TRỌ NGÕ 1 PHỐ PHAN ĐÌNH GIÓT, THANH XUÂN, NỘI THẤT ĐẦY ĐỦ','Thông tin mô tả\nKhông chung chủ, chỗ để xe thoải mái, nhà mới khai trương, nội thất đầy đủ, wifi, bình nóng lạnh, máy lọc nước, ban công, khu bếp mới 100%, camera an ninh, điện nước có công tơ đo riêng, oto đỗ cửa\nPhòng 30m2 giá thuê 4.5 Triệu/Tháng\nTại 106 ngõ 1 Đường Phan Đình Giót, Phường Phương Liệt, Quận Thanh Xuân, Hà Nội\nLiên hệ: 0942721906','Thanh Xuân, Hà Nội','Thanh Xuân',' Hà Nội',20.9959212,105.8040796,4500000,30,'APPROVED',NULL,'2025-10-25 09:59:49','2025-11-17 14:35:33'),(6,1,'CHO THUÊ 1 PHÒNG MASTER KHÉP KÍN TRONG CĂN HỘ CHUNG CƯ – FULL NỘI THẤT, Ở TỪ THÁNG 11','Thông tin mô tả\nCHO THUÊ 1 PHÒNG MASTER KHÉP KÍN TRONG CĂN HỘ – FULL NỘI THẤT, Ở TỪ THÁNG 11\n- Địa chỉ: Chung cư ia20 Ciputra, Bắc Từ Liêm\nKhu vực yên tĩnh, tiện ích thương mại siêu thị, hiệu thuốc, phòng gym, spa… Thuận tiện di chuyển các tuyến đường vành đai, sân bay, gần hồ tây, sát các trục đường lớn Phạm Văn Đồng, Võ Chí Công…\n- Loại phòng: Phòng Master rộng rãi – có WC riêng\n- Diện tích phòng: khoảng 30m2\n- Giá cho thuê: 5.8 triệu\n- Tiện ích: Phòng rộng, thoáng mát, nhà mới\n- Nội thất đầy đủ: Giường, nệm, tủ qao, điều hoà, bàn làm việc, WC riêng nóng lạnh đầy đủ\n- Căn hộ có bếp, máy giặt, tủ lạnh, phòng khách dùng chung\n- Căn 2N, không chung chủ, nhà chỉ có 2 người, đảm bảo không gian riêng tư\n- An ninh 24/7, thang máy, giữ xe, thẻ từ ra vào\n- Liên hệ: 0967685751','Bắc Từ Liêm, Hà Nội','Bắc Từ Liêm',' Hà Nội',21.0730201,105.7703287,5800000,30,'APPROVED',NULL,'2025-10-25 09:59:49','2025-11-17 14:35:33'),(7,1,'CHO THUÊ PHÒNG NGAY THỤY KHUÊ, TÂY HỒ – CHỈ 2,7 TRIỆU/THÁNG','Thông tin mô tả\nPHÒNG TRỌ GIÁ RẺ – THỤY KHUÊ, TÂY HỒ\n 19B ngõ 530 Thụy Khuê – gần Hồ Tây, ĐH Điện Lực, Nội Vụ, Du Lịch...\nTiện nghi đầy đủ: giường, tủ, đệm, điều hòa, nóng lạnh, bàn làm việc\nMáy giặt dùng chung – gửi xe miễn phí\nNhà 4 tầng, thang bộ\nGiá chỉ 2,1tr/tháng\nĐiện 3.800đ/số | Nước 100k/người | DV 150k/người\nƯu đãi: Cọc 1 tháng, đóng 1 tháng\n Liên hệ Anh Nguyên: 0904 525 414','Tây Hồ, Hà Nội','Tây Hồ',' Hà Nội',21.0738016,105.8231588,2700000,20,'APPROVED',NULL,'2025-10-25 09:59:49','2025-11-17 14:35:33'),(8,1,'Cho thuê phòng đẹp giá 4,2 tr phố Nguyễn Khuyến, Đống Đa đi bộ ra Ga Hà Nội, Văn Miếu Quốc Tử Giám','Thông tin mô tả\nĐịa chỉ: Nhà 111A Nguyễn Khuyến.\nTrống phòng vào ở ngay, gần phố đi lại thuận tiện vài bước chân ra ga Hà Nội, Văn Miếu.\nXem phòng full time.\nCòn 7 phòng giá từ 4.200.000 - 4.800.000 tr.\nVệ sinh chung khép kín đủ đồ cơ bản (thêm tủ lạnh 200k).\nCầu thang bộ.\nÔ tô đỗ cửa.\nMặt phố Nguyễn KHuyến.\nGần Ga Hà Nội, Văn Miếu tiện sang Đại học Bách Khoa, ĐH Xây Dựng, ĐH Kinh tế quốc dân, Học viện Ngân hàng, ĐH Thủy Lợi, ĐH Công Đoàn, ngay bến xe bus, ĐH văn hóa, ĐH Mỹ Thuật,...\nNội thất: Giường tủ, đệm, điều hòa nóng lạnh, máy giặt chung, bàn bếp..., khoá vân tay, Thang bộ.\n- Giờ giấc tự do, Không chung chủ, không giới hạn ở, mỗi phòng 2 xe.\nPhí dịch vụ: Điện 4,0 k/1 số.\nNước 120k/ 1ng,\nDịch vụ chung 150k / người.\n- Thanh toán 1 cọc 1.\n- HĐ 6 - 12 tháng - xem phòng full time.\nLiên hệ: A Nguyên 0904 525 414.','Đống Đa, Hà Nội','Đống Đa',' Hà Nội',21.0147317,105.8349009,4200000,24,'APPROVED',NULL,'2025-10-25 09:59:49','2025-11-17 14:35:33'),(9,1,'CHO THUÊ PHÒNG TRỌ KHÉP KÍN – ĐỦ ĐỒ – GIÁ RẺ CHỈ 2,5TR/THÁNG – MỸ ĐÌNH, NAM TỪ LIÊM','Thông tin mô tả\nCHO THUÊ PHÒNG TRỌ KHÉP KÍN – ĐỦ ĐỒ – GIÁ RẺ CHỈ 2,5TR/THÁNG – MỸ ĐÌNH, NAM TỪ LIÊM \nĐịa chỉ: Số 28, ngõ 5, tổ 15, Mỹ Đình 1, Nam Từ Liêm – ngay sau SVĐ Mỹ Đình.\nGần nhiều trường: CĐ Bách Khoa, CĐ FPT, ĐH Đông Á, ĐH Thành Đô, CĐ Đại Việt, CĐ Bách Nghệ, ĐH Thương Mại, Sân khấu Điện ảnh…\nPhòng khép kín, full nội thất: điều hòa, nóng lạnh, giường, tủ, tủ bếp…\nGiá siêu rẻ: 2,5 triệu/tháng.\n* Dịch vụ:\nĐiện: 4k/kw\nNước: 120k/người\nDV chung: 150k/người/tháng\n* Lưu ý:\nHợp đồng 6–12 tháng\nCọc 1 tháng, thanh toán 1 tháng\nLiên hệ xem phòng: Anh Nguyên: 0969 153 598 / 0904 525 414\nChị Phượng: 0985 991 384','Nam Từ Liêm, Hà Nội','Nam Từ Liêm',' Hà Nội',21.0034608,105.7703287,2500000,20,'APPROVED',NULL,'2025-10-25 09:59:49','2025-11-17 14:35:33'),(10,1,'cho thuê phòng trọ giá rẻ 2,2 tr đẩy đủ nội thất, Phúc Diễn, Xuân Phương, Nam từ Liêm','Thông tin mô tả\nCHO THUÊ PHÒNG TRỌ - 639 PHÚC DIỄN, NAM TỪ LIÊM\nCòn trống 2 phòng – Vào ở ngay!\nGần: CĐ Bách Khoa, CĐ FPT, ĐH Đông Á, ĐH Thành Đô, ĐH Thương Mại, Sân khấu Điện ảnh...\nPhòng 103 – Vệ sinh khép kín, full đồ\nGiá: 2.3 triệu/tháng\nNội thất đầy đủ: Giường, tủ, đệm, điều hòa, nóng lạnh, máy giặt chung\nKhóa vân tay – Ô tô đỗ cửa\nDịch vụ:\nĐiện: 4.000đ/số\nNước: 120k/